CREATE OR REPLACE FUNCTION public.parent_can_view_sales_invoice(p_invoice_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public SET row_security = off AS $$ SELECT EXISTS (SELECT 1 FROM public.invoice_line_items ili CROSS JOIN LATERAL unnest(COALESCE(ili.session_ids, ARRAY[]::uuid[])) AS sid(session_id) INNER JOIN public.sessions sess ON sess.id = sid.session_id WHERE ili.invoice_id = p_invoice_id AND public.parent_can_access_student(sess.student_id)) OR EXISTS (SELECT 1 FROM public.lesson_packages lp WHERE lp.manual_sales_invoice_id = p_invoice_id AND public.parent_can_access_student(lp.student_id)); $$; REVOKE ALL ON FUNCTION public.parent_can_view_sales_invoice(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.parent_can_view_sales_invoice(uuid) TO authenticated, service_role; DROP POLICY IF EXISTS "invoices_parent_select" ON public.invoices; CREATE POLICY "invoices_parent_select" ON public.invoices FOR SELECT USING (public.parent_can_view_sales_invoice(id)); DROP POLICY IF EXISTS "invoice_line_items_parent_select" ON public.invoice_line_items; CREATE POLICY "invoice_line_items_parent_select" ON public.invoice_line_items FOR SELECT USING (public.parent_can_view_sales_invoice(invoice_line_items.invoice_id)); DROP POLICY IF EXISTS "org_parent_can_read_child_org" ON public.organizations; CREATE POLICY "org_parent_can_read_child_org" ON public.organizations FOR SELECT USING (id IN (SELECT COALESCE(s.organization_id, p.organization_id) FROM public.students s LEFT JOIN public.profiles p ON p.id = s.tutor_id WHERE public.parent_can_access_student(s.id) AND COALESCE(s.organization_id, p.organization_id) IS NOT NULL)); CREATE OR REPLACE FUNCTION public.can_read_profile_as_parent(p_profile_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public SET row_security = off AS $$ SELECT EXISTS (SELECT 1 FROM public.students s WHERE s.tutor_id = p_profile_id AND public.parent_can_access_student(s.id)); $$; REVOKE ALL ON FUNCTION public.can_read_profile_as_parent(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_read_profile_as_parent(uuid) TO authenticated, service_role;;
